-- 006's named autogenerated grant constraint was confirmed through pg_catalog.
ALTER TABLE agent_connections DROP CONSTRAINT agent_connections_check1;
ALTER TABLE agent_connections ADD CONSTRAINT agent_connections_fixture_grants CHECK(provider <> 'fixture' OR (scopes <@ ARRAY['documents:read','notes:write']::text[] AND resource_ids <@ ARRAY['doc-alpha','doc-beta']::text[]));
CREATE TABLE agent_action_proposals (
 id uuid PRIMARY KEY,
 owner_id text NOT NULL REFERENCES auth_users(id),
 conversation_id uuid NOT NULL REFERENCES agent_conversations(id),
 sequence integer NOT NULL,
 payload jsonb NOT NULL,
 digest text NOT NULL CHECK(length(digest)=64),
 state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','approved','rejected','executed','blocked','expired','needs_review')),
 attempts integer NOT NULL DEFAULT 0,
 decided_by text REFERENCES auth_users(id),
 decided_digest text,
 decided_at timestamptz,
 error_code text,
 created_at timestamptz NOT NULL DEFAULT now(),
 updated_at timestamptz NOT NULL DEFAULT now(),
 FOREIGN KEY(conversation_id,sequence) REFERENCES conversation_turns(conversation_id,sequence)
);
CREATE INDEX agent_action_proposals_owner ON agent_action_proposals(owner_id,created_at DESC);
CREATE FUNCTION reject_action_payload_mutation() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Action proposals are immutable'; END IF;
 IF NEW.id IS DISTINCT FROM OLD.id OR NEW.owner_id IS DISTINCT FROM OLD.owner_id OR NEW.conversation_id IS DISTINCT FROM OLD.conversation_id OR NEW.sequence IS DISTINCT FROM OLD.sequence OR NEW.payload IS DISTINCT FROM OLD.payload OR NEW.digest IS DISTINCT FROM OLD.digest OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN RAISE EXCEPTION 'Action payloads are immutable'; END IF;
 RETURN NEW;
END;
$$;
CREATE TRIGGER immutable_action_payload BEFORE UPDATE OR DELETE ON agent_action_proposals FOR EACH ROW EXECUTE FUNCTION reject_action_payload_mutation();
CREATE TABLE fixture_note_targets (
 owner_id text NOT NULL REFERENCES auth_users(id),
 connection_id uuid NOT NULL REFERENCES agent_connections(id),
 resource_id text NOT NULL CHECK(resource_id IN ('doc-alpha','doc-beta')),
 version integer NOT NULL DEFAULT 0 CHECK(version>=0),
 PRIMARY KEY(owner_id,connection_id,resource_id)
);
CREATE TABLE fixture_note_effects (
 proposal_id uuid PRIMARY KEY REFERENCES agent_action_proposals(id),
 owner_id text NOT NULL REFERENCES auth_users(id),
 connection_id uuid NOT NULL REFERENCES agent_connections(id),
 resource_id text NOT NULL,
 target_version integer NOT NULL,
 note text NOT NULL CHECK(length(note) BETWEEN 1 AND 500),
 receipt jsonb NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(owner_id,connection_id,resource_id,target_version)
);
CREATE FUNCTION reject_fixture_effect_mutation() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'Fixture receipts are immutable'; END;
$$;
CREATE TRIGGER immutable_fixture_effect BEFORE UPDATE OR DELETE ON fixture_note_effects FOR EACH ROW EXECUTE FUNCTION reject_fixture_effect_mutation();
